            h("label", { class: "check" }, h("input", { type: "checkbox", checked: cfg.tcs, onchange: (e) => upd("tcs", e.target.checked) }), "\u0410\u043D\u0442\u0438\u043F\u0440\u043E\u0431\u0443\u043A\u0441\u043E\u0432\u043A\u0430")
